import math, json

def F(t):
    # antiderivative of ln(1+t)/t^2, t = x-2
    return -math.log1p(t)/t + math.log(t) - math.log1p(t)

def first(eps, delta):   # integral over x in [2+delta, 2+eps]
    return F(eps) - F(delta)

def second(eps):         # integral over x in [3-eps, 3], t in [1-eps, 1]
    return F(1.0) - F(1.0 - eps)

eps = 1e-3
